<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {request,post} from '../api/client'
import {requestUUID} from '../utils/request-uuid'
interface Archive{id:string;assetId:string;originalPath:string;archivePath:string;kind:string;archivedAt:string;eligibleAfter:string;state:string;cleanupId?:string;message:string;deletedAt?:string}
interface Policy{retentionDays:number;revision:number;automaticCleanup:boolean}
interface Preview{planDigest:string;policy:Policy;items:Archive[];sourceFilesUntouched:boolean;physicalDeletion:boolean}
interface Result{id:string;archiveId:string;state:string;message:string}
const items=ref<Archive[]>([]),policy=ref<Policy|null>(null),days=ref(30),page=ref(1),total=ref(0),selected=ref<Archive[]>([]),loading=ref(false),saving=ref(false),previewing=ref(false),applying=ref(false),error=ref(''),confirmation=ref(''),dialog=ref(false),plan=ref<Preview|null>(null),requestId=ref('')
let timer:ReturnType<typeof setInterval>|undefined
function eligible(a:Archive){return a.state==='retained'&&!a.deletedAt&&new Date(a.eligibleAfter).getTime()<=Date.now()}
function stateLabel(state:string){return ({retained:'保留中',approved:'已批准，待继续',quarantined:'已隔离，待完成',removed:'已清理（审计保留）',conflict:'冲突，未继续删除'} as Record<string,string>)[state]??state}
async function refresh(){if(loading.value||dialog.value||applying.value)return;loading.value=true;try{const [data,current]=await Promise.all([request<{items:Archive[];total:number}>(`/library/archives?page=${page.value}&pageSize=50`),request<Policy>('/library/archive-policy')]);items.value=data.items;total.value=data.total;policy.value=current;days.value=current.retentionDays;selected.value=[];error.value=''}catch(e){error.value=e instanceof Error?e.message:'归档记录不可用'}finally{loading.value=false}}
async function savePolicy(){if(!policy.value)return;saving.value=true;try{policy.value=await post<Policy>('/library/archive-policy',{retentionDays:days.value,revision:policy.value.revision,automaticCleanup:false});ElMessage.success('保留期已保存；不会自动删除归档');await refresh()}catch(e){ElMessage.error(e instanceof Error?e.message:'保留期保存失败')}finally{saving.value=false}}
async function preview(){if(selected.value.length<1||selected.value.length>20)return;previewing.value=true;try{plan.value=await post<Preview>('/library/archives/cleanup-preview',{archiveIds:selected.value.map(a=>a.id)});confirmation.value='';requestId.value=requestUUID();dialog.value=true}catch(e){ElMessage.error(e instanceof Error?e.message:'归档内容、归属或保留期尚未验证')}finally{previewing.value=false}}
async function apply(){if(!plan.value||confirmation.value!=='清理归档')return;applying.value=true;try{const results=await post<Result[]>('/library/archives/cleanup-confirm',{requestId:requestId.value,archiveIds:plan.value.items.map(a=>a.id),planDigest:plan.value.planDigest});if(results.length!==plan.value.items.length){throw new Error('清理结果不完整，请保留本次请求ID核对已有请求结果')};const completed=results.filter(r=>r.state==='removed').length;dialog.value=false;if(completed===results.length)ElMessage.success(`已清理${completed}项明确批准的过期归档；未操作原媒体`);else ElMessage.warning(`${completed}项已完成，其余已批准或冲突，请核对记录后明确重试`)}catch(e){ElMessage.error(e instanceof Error?e.message:'清理结果未确认；保留当前请求，不要换ID重复提交')}finally{applying.value=false;if(!dialog.value)await refresh()}}
async function reconcile(){if(!requestId.value)return;try{const results=await request<Result[]>(`/library/archive-cleanups/${requestId.value}`);if(!results.length){ElMessage.warning('尚未确认批准记录，可保留同一请求ID再确认，不换计划重复提交');return};const completed=results.filter(r=>r.state==='removed').length;dialog.value=false;ElMessage.info(`${completed}项已完成，其余请在归档列表核对并明确重试`);await refresh()}catch(e){ElMessage.error(e instanceof Error?e.message:'请求状态未确认，不自动重试删除')}}
async function retry(a:Archive){if(!a.cleanupId)return;try{await ElMessageBox.confirm('仅继续这项已有批准的归档清理。仍会检查当前文件、资产状态及保留期；手工改动将被拒绝。','继续已批准的归档清理',{type:'warning',confirmButtonText:'明确继续',cancelButtonText:'取消'});await post(`/library/archive-cleanups/${a.cleanupId}/retry`,{});ElMessage.success('已有批准操作已完成');await refresh()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
onMounted(()=>{refresh();timer=setInterval(refresh,15000)});onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template>
<section class="panel section-gap"><div class="panel-title"><h2>旧输出归档 <small>{{total}}项</small></h2><el-button :loading="loading" @click="refresh">刷新归档</el-button></div>
<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<p class="field-hint">只管理完成输出迁移后生成的.retired归档，不清理网盘/做种源文件、当前STRM或共享NFO。过期仅表示可预览；没有自动删除任务。</p>
<div class="archive-policy"><label for="archive-retention">归档保留天数</label><el-input-number id="archive-retention" v-model="days" :min="1" :max="3650" aria-label="归档保留天数"/><el-button :loading="saving" :disabled="!policy" @click="savePolicy">保存保留期</el-button><el-button :loading="previewing" :disabled="selected.length<1||selected.length>20" @click="preview">预览清理所选 {{selected.length||''}}</el-button></div>
<el-table :data="items" row-key="id" @selection-change="selected=$event" empty-text="没有已完成的输出归档。不会扫描任意过期文件进行清理。"><el-table-column type="selection" width="45" :selectable="eligible"/><el-table-column label="原输出 / 归档" min-width="300"><template #default="s"><strong>{{s.row.originalPath}}</strong><p class="field-hint archive-path">{{s.row.archivePath}}</p></template></el-table-column><el-table-column label="状态 / 保留至" min-width="200"><template #default="s">{{stateLabel(s.row.state)}}<p class="field-hint">{{new Date(s.row.eligibleAfter).toLocaleString()}}</p><p class="field-hint">{{s.row.message}}</p></template></el-table-column><el-table-column label="操作" width="170"><template #default="s"><el-button v-if="s.row.cleanupId&&s.row.state!=='removed'" @click="retry(s.row)">继续已批准清理</el-button></template></el-table-column></el-table>
<el-pagination v-model:current-page="page" :page-size="50" :total="total" layout="prev,pager,next,total" @current-change="refresh"/>
<el-dialog v-model="dialog" append-to-body title="确认物理清理归档" width="min(700px,95vw)" :close-on-click-modal="false"><el-alert title="这会物理删除下面明确选中的过期托管归档，不能自动撤销。原媒体、做种源文件、当前输出与共享NFO不在计划中。" type="warning" :closable="false"/><ul class="archive-plan" aria-label="归档清理计划"><li v-for="a in plan?.items??[]" :key="a.id"><strong>{{a.kind}} · {{a.originalPath}}</strong><code>{{a.archivePath}}</code></li></ul><p class="field-hint">确认时重新检查摘要、归属、当前输出和保留期；旧计划或手工改动将阻止清理。请求结果不确定时保留请求ID以查询，不自动重试删除。</p><p class="field-hint archive-path">本次请求ID：{{requestId}}</p><el-button :disabled="applying" @click="reconcile">核对已有请求结果</el-button><label for="archive-confirmation">输入“清理归档”确认</label><el-input id="archive-confirmation" v-model="confirmation" aria-label="输入清理归档确认" autocomplete="off"/><template #footer><el-button :disabled="applying" @click="dialog=false">返回检查</el-button><el-button type="danger" :loading="applying" :disabled="confirmation!=='清理归档'" @click="apply">确认物理清理</el-button></template></el-dialog>
</section>
</template>
<style scoped>.archive-policy{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:16px 0}.archive-path{overflow-wrap:anywhere}.archive-plan{list-style:none;padding:0;max-height:40vh;overflow:auto}.archive-plan li{padding:12px 0;border-bottom:1px solid var(--border)}.archive-plan code{display:block;white-space:normal;overflow-wrap:anywhere;font-size:13px;line-height:1.6;margin-top:6px}.el-pagination{margin-top:16px;overflow:auto}.panel-title small{font-size:13px;color:var(--muted);font-weight:400}</style>
